/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER trg_prov_marks_audit_ai
AFTER INSERT ON acad_course_registration
FOR EACH ROW
BEGIN
  DECLARE v_actor  VARCHAR(90);
  DECLARE v_source VARCHAR(100);
  DECLARE v_reason VARCHAR(200);
  DECLARE v_ip     VARCHAR(45);
  DECLARE CONTINUE HANDLER FOR NOT FOUND BEGIN END;

  IF NEW.provisional_course_work_marks IS NOT NULL
     OR NEW.provisional_exam_marks IS NOT NULL THEN

    SELECT actor, source, reason, ip INTO v_actor, v_source, v_reason, v_ip
      FROM campus_dynamics.mark_audit_context
     WHERE conn_id = CONNECTION_ID()
       AND set_at >= (NOW() - INTERVAL 60 SECOND)
     LIMIT 1;

    INSERT INTO acad_provisional_marks_audit
      (reg_id, regno, course_id, prog_id, acad_year, semester, action_type,
       changed_cw, changed_exam,
       old_cw, new_cw, old_exam, new_exam, old_total, new_total,
       old_status, new_status,
       performed_by, source_page, change_reason, ip_address, created_at)
    VALUES
      (IFNULL(NEW.ID,0), IFNULL(NEW.regno,''), IFNULL(NEW.courseID,''), NEW.prog_id,
       NEW.acad_year, NEW.semester, 'INSERT',
       (NEW.provisional_course_work_marks IS NOT NULL),
       (NEW.provisional_exam_marks IS NOT NULL),
       NULL, NEW.provisional_course_work_marks,
       NULL, NEW.provisional_exam_marks,
       NULL, NEW.provisional_total_marks,
       NULL, NEW.provisional_marks_status,
       IFNULL(NULLIF(TRIM(v_actor),''),'system'),
       IFNULL(NULLIF(TRIM(v_source),''),'db-trigger'),
       NULLIF(TRIM(v_reason),''), NULLIF(TRIM(v_ip),''), NOW());
  END IF;
END */;;
DELIMITER ;
